INSERT INTO `contract` (`contract_no`, `contract_name`, `party_a`, `party_b`, `sign_date`, `start_date`, `end_date`, `contract_amount`, `currency`, `contract_type`, `status`, `employee_id`, `employee_name`, `department`, `contract_content`, `remark`) VALUES
('HT-2026-001', '劳动合同-张三', '菜鸟网络科技有限公司', '张三', '2026-01-01', '2026-01-01', '2029-12-31', 150000.00, 'CNY', '劳动合同', '生效中', 1, '张三', '技术部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：张三</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2026年1月1日起至2029年12月31日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方技术部担任高级工程师职务，负责系统架构设计与开发工作。</p><h3>四、劳动报酬</h3><p>乙方月工资为12500元人民币，每年根据公司绩效进行调整。</p><h3>五、工作时间和休息休假</h3><p>实行标准工时制，每日工作8小时，每周工作5天。乙方享受国家法定节假日及公司规定的带薪年假。</p>', '正式员工劳动合同'),
('HT-2026-002', '劳动合同-李四', '菜鸟网络科技有限公司', '李四', '2026-02-15', '2026-02-15', '2029-02-14', 120000.00, 'CNY', '劳动合同', '生效中', 2, '李四', '技术部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：李四</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2026年2月15日起至2029年2月14日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方技术部担任开发工程师职务，负责前端系统开发工作。</p><h3>四、劳动报酬</h3><p>乙方月工资为10000元人民币，每年根据公司绩效进行调整。</p>', '正式员工劳动合同'),
('HT-2026-003', '劳动合同-王五', '菜鸟网络科技有限公司', '王五', '2025-06-01', '2025-06-01', '2028-05-31', 240000.00, 'CNY', '劳动合同', '生效中', 3, '王五', '技术部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：王五</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2025年6月1日起至2028年5月31日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方技术部担任技术经理职务，负责部门管理及技术规划工作。</p><h3>四、劳动报酬</h3><p>乙方月工资为20000元人民币，享受部门经理绩效奖金。</p>', '部门领导劳动合同'),
('HT-2026-004', '保密协议-张三', '菜鸟网络科技有限公司', '张三', '2026-01-01', '2026-01-01', '2031-12-31', 0.00, 'CNY', '保密协议', '生效中', 1, '张三', '技术部', '<h3>保密协议</h3><p><strong>甲方（用人单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳动者）：</strong>张三</p><h3>第一条 保密信息定义</h3><p>本协议所称保密信息，是指甲方及其关联公司拥有或控制的，未公开的技术信息、商业信息、财务信息及其他保密信息。</p><h3>第二条 保密义务</h3><p>乙方承诺在任职期间及离职后五年内，对保密信息严格保密，不以任何方式披露、使用或允许他人使用。</p><h3>第三条 违约责任</h3><p>若乙方违反本协议约定，应向甲方支付违约金，并赔偿由此造成的一切损失。</p>', '员工保密协议'),
('HT-2026-005', '培训协议-赵六', '菜鸟网络科技有限公司', '赵六', '2026-03-01', '2026-03-01', '2028-02-28', 50000.00, 'CNY', '培训协议', '生效中', 4, '赵六', '技术部', '<h3>培训服务协议</h3><p><strong>甲方（用人单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳动者）：</strong>赵六</p><h3>第一条 培训内容</h3><p>甲方为乙方提供为期6个月的高级技术培训，培训内容包括人工智能、云计算等前沿技术。</p><h3>第二条 培训费用</h3><p>甲方承担培训费用共计50000元人民币。</p><h3>第三条 服务期约定</h3><p>乙方承诺在培训结束后为甲方服务满2年。若乙方提前离职，需按未履行服务期比例退还培训费用。</p>', '技术培训协议'),
('HT-2026-006', '劳务合同-钱七', '菜鸟网络科技有限公司', '钱七', '2026-04-01', '2026-04-01', '2026-09-30', 30000.00, 'CNY', '劳务合同', '生效中', 5, '钱七', '市场部', '<h3>劳务合同</h3><p><strong>甲方（用工单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳务人员）：</strong>钱七</p><h3>第一条 劳务内容</h3><p>乙方为甲方提供市场推广及活动策划服务。</p><h3>第二条 劳务期限</h3><p>自2026年4月1日起至2026年9月30日止。</p><h3>第三条 劳务报酬</h3><p>乙方劳务报酬为5000元/月，按月结算。</p>', '短期劳务合同'),
('HT-2026-007', '劳动合同-孙八', '菜鸟网络科技有限公司', '孙八', '2024-07-01', '2024-07-01', '2027-06-30', 96000.00, 'CNY', '劳动合同', '生效中', 6, '孙八', '人力资源部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：孙八</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2024年7月1日起至2027年6月30日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方人力资源部担任人事专员职务，负责员工招聘及培训工作。</p>', '人力资源部劳动合同'),
('HT-2026-008', '劳动合同-周九', '菜鸟网络科技有限公司', '周九', '2023-03-15', '2023-03-15', '2026-03-14', 108000.00, 'CNY', '劳动合同', '已到期', 7, '周九', '财务部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：周九</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2023年3月15日起至2026年3月14日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方财务部担任会计职务。</p>', '合同已到期，等待续签'),
('HT-2026-009', '保密协议-郑十一', '菜鸟网络科技有限公司', '郑十一', '2025-08-01', '2025-08-01', '2030-07-31', 0.00, 'CNY', '保密协议', '生效中', 10, '郑十一', '技术部', '<h3>保密协议</h3><p><strong>甲方（用人单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳动者）：</strong>郑十一</p><h3>第一条 保密信息定义</h3><p>本协议所称保密信息，是指甲方及其关联公司拥有或控制的，未公开的技术信息、商业信息、财务信息及其他保密信息。</p><h3>第二条 保密义务</h3><p>乙方承诺在任职期间及离职后五年内，对保密信息严格保密。</p>', '部门领导保密协议'),
('HT-2026-010', '劳动合同-吴十二', '菜鸟网络科技有限公司', '吴十二', '2025-11-01', '2025-11-01', '2028-10-31', 144000.00, 'CNY', '劳动合同', '生效中', 11, '吴十二', '运营部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：吴十二</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2025年11月1日起至2028年10月31日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方运营部担任运营主管职务，负责日常运营管理工作。</p>', '运营部劳动合同'),
('HT-2026-011', '劳务合同-郑十三', '菜鸟网络科技有限公司', '郑十三', '2026-01-01', '2026-01-01', '2026-06-30', 24000.00, 'CNY', '劳务合同', '已到期', 12, '郑十三', '行政部', '<h3>劳务合同</h3><p><strong>甲方（用工单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳务人员）：</strong>郑十三</p><h3>第一条 劳务内容</h3><p>乙方为甲方提供行政后勤服务。</p><h3>第二条 劳务期限</h3><p>自2026年1月1日起至2026年6月30日止。</p>', '劳务合同已到期'),
('HT-2026-012', '培训协议-张三', '菜鸟网络科技有限公司', '张三', '2026-06-01', '2026-06-01', '2028-05-31', 30000.00, 'CNY', '培训协议', '待签署', 1, '张三', '技术部', '<h3>培训服务协议</h3><p><strong>甲方（用人单位）：</strong>菜鸟网络科技有限公司</p><p><strong>乙方（劳动者）：</strong>张三</p><h3>第一条 培训内容</h3><p>甲方计划为乙方提供为期3个月的架构师培训。</p><h3>第二条 培训费用</h3><p>甲方承担培训费用共计30000元人民币。</p><h3>第三条 服务期约定</h3><p>乙方承诺在培训结束后为甲方服务满2年。</p>', '待员工签署'),
('HT-2026-013', '劳动合同-王十四', '菜鸟网络科技有限公司', '王十四', '2026-05-01', '2026-05-01', '2029-04-30', 132000.00, 'CNY', '劳动合同', '生效中', 13, '王十四', '市场部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：王十四</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2026年5月1日起至2029年4月30日止。</p><h3>三、工作内容</h3><p>乙方同意在甲方市场部担任市场经理职务，负责市场拓展工作。</p>', '市场部劳动合同'),
('HT-2026-014', '其他协议-技术合作', '菜鸟网络科技有限公司', '阿里云科技有限公司', '2026-01-15', '2026-01-15', '2027-01-14', 500000.00, 'CNY', '其他', '生效中', NULL, NULL, '技术部', '<h3>技术合作协议</h3><p><strong>甲方：</strong>菜鸟网络科技有限公司</p><p><strong>乙方：</strong>阿里云科技有限公司</p><h3>第一条 合作内容</h3><p>甲乙双方就云计算技术服务达成合作协议，乙方为甲方提供云计算基础设施服务。</p><h3>第二条 服务费用</h3><p>甲方每年向乙方支付服务费用50万元人民币。</p><h3>第三条 合作期限</h3><p>自2026年1月15日起至2027年1月14日止。</p>', '公司间技术合作协议'),
('HT-2026-015', '劳动合同-李十五', '菜鸟网络科技有限公司', '李十五', '2022-08-01', '2022-08-01', '2025-07-31', 84000.00, 'CNY', '劳动合同', '已终止', 14, '李十五', '客服部', '<h3>一、劳动合同双方基本情况</h3><p>甲方（用人单位）：菜鸟网络科技有限公司</p><p>乙方（劳动者）：李十五</p><h3>二、合同期限</h3><p>本合同为固定期限劳动合同，自2022年8月1日起至2025年7月31日止。</p><h3>三、合同终止</h3><p>因乙方个人原因提出辞职，合同已于2025年7月31日终止。</p>', '员工已离职，合同终止');
